// План specs/billing.md 3.1 / 3.2 (#2185f2). Pre-Prod, preprod-a (Starter Tech, trial). Отмена НЕ подтверждается:
// открываем окно, читаем текст, закрываем «Keep my plan» (в окне). Кнопка «Cancel subscription» в окне не нажимается.
// Источник: «מה רצוי» — окно перед отменой: до какой даты план активен, что дальше (Techory Lite), что ничего не удаляется;
// реджект Р2 — в окне имя оплаченного пакета, не «Techory Lite». Факты 17.11: «Starter Tech stays active until Nov 3, 2026», HE «ביטול המנוי».
// Если подписка уже в состоянии «Cancels on …» (кнопки «Cancel subscription» нет) — тест пропускается.
import { test, expect } from '../../fixtures';
import { SUB_ROLE, cancelDialog, cancelSubscriptionButton, openBillingDirect, subscriptionRow } from './billing-helpers';

test.describe('Billing — Cancel subscription window (#2185f2)', () => {
  test('Cancel subscription → window names the paid plan and date, explains Lite; "Keep my plan" closes it, nothing is cancelled #2185f2 @desktop', async ({ asUser }) => {
    const page = await asUser(SUB_ROLE);
    await openBillingDirect(page);

    const cancel = cancelSubscriptionButton(page);
    test.skip((await cancel.count()) === 0, 'подписка уже отменена («Cancels on…») — кнопки Cancel subscription нет');
    // На десктопе кнопка — в колонке Actions строки Techory
    await expect(subscriptionRow(page, 'Techory').getByRole('button', { name: 'Cancel subscription', exact: true })).toBeVisible();

    await cancel.click();
    const dialog = cancelDialog(page, 'Cancel your Techory subscription?');
    await expect(dialog).toBeVisible();
    // Имя оплаченного пакета и дата, не «Techory Lite» (реджект Р2)
    await expect(dialog).toContainText(/\S.* stays active until [A-Z][a-z]{2} \d{1,2}, \d{4}\. You will not be charged again\./);
    await expect(dialog).not.toContainText('Techory Lite stays active');
    // Что будет после (текст программиста 10.11): переход на бесплатный Lite, ничего не удаляется
    await expect(dialog).toContainText('free Techory Lite plan');
    await expect(dialog).toContainText('Nothing you have saved is deleted');
    await expect(dialog.getByRole('button', { name: 'Keep my plan', exact: true })).toBeVisible();
    await expect(dialog.getByRole('button', { name: 'Cancel subscription', exact: true })).toBeVisible();

    // Keep my plan в окне: окно закрыто, отмена не произошла
    await dialog.getByRole('button', { name: 'Keep my plan', exact: true }).click();
    await expect(dialog).toBeHidden();
    await expect(page.getByText(/^Cancels on /)).toHaveCount(0);
    await expect(cancel).toBeVisible();
  });

  test('HE: the button reads «ביטול המנוי», the window is right-to-left and offers «להשאיר את החבילה» #2185f2 @desktop', async ({ asUser }) => {
    const page = await asUser(SUB_ROLE);
    await openBillingDirect(page, 'he');

    const cancel = cancelSubscriptionButton(page, 'ביטול המנוי');
    test.skip((await cancel.count()) === 0, 'подписка уже отменена — кнопки «ביטול המנוי» нет');
    await cancel.click();

    const dialog = cancelDialog(page, /לבטל את המנוי/);
    await expect(dialog).toBeVisible();
    await expect(dialog).toContainText(/נשארת פעילה עד/);
    await expect(dialog.getByRole('button', { name: 'ביטול המנוי', exact: true })).toBeVisible();
    await expect(dialog.getByRole('button', { name: 'להשאיר את החבילה', exact: true })).toBeVisible();
    await expect(page.locator('html')).toHaveAttribute('dir', 'rtl');

    await dialog.getByRole('button', { name: 'להשאיר את החבילה', exact: true }).click();
    await expect(dialog).toBeHidden();
  });
});
